## Assignment:

Make the pop method!

- [ ] Make the operator[] throw the error "Unable to access out-of-bounds index" (casted as a string) if index is less than length - 1.
- [ ] Make the `void pop()` method:
  - [ ] If length is < 1 throw "Cannot pop a empty vector" (casted as a string).
  - [ ] Otherwise, subtract one from length.

starterCode:
#include <iostream> // for the test harness
#include <string>
#include <initializer_list>
#include <algorithm>
template <typename T, int S = 1>
class DynamArr {
private:
    T* value;
    int max_length;
public:
    int length;
    DynamArr(std::initializer_list<T> init) {
        this->length = init.size();
        this->max_length = (S > 1 ? S : init.size()) * 2;
        this->value = new T[this->max_length];
        std::copy(init.begin(), init.end(), this->value);
    }
    DynamArr() {
        this->length = 0;
        this->max_length = (S > 1 ? S : 1) * 2;
        this->value = new T[this->max_length];
    }
    T& operator[](size_t index) {
        return this->value[index];
    }
    const T& operator[](size_t index) const {
        return this->value[index];
    }
    const T back() const {
        return this->value[this->length - 1];
    }
    const T front() const {
        return this->value[0];
    }
    const T* data() const {
        return this->value;
    }
    ~DynamArr() {
        delete[] this->value;
        this->value = nullptr;
    }
    void push(T val) {
        if (length >= max_length) {
            max_length *= 2;
            T* old = this->value;
            this->value = new T[this->max_length];
            std::copy(old, old + this->length, this->value);
            delete[] old;
            old = nullptr;
        }
        this->value[this->length++] = val;
    }
};

runHarness:
int _pass = 0;
int _fail = 0;
void _test(int num, int got, int expected) {
    bool passed = got == expected;
    std::cout << "---------------------\n";
    std::cout << "Test " << num << ":\n";
    std::cout << (passed ? "Pass" : "Fail") << "\n";
    if (passed) _pass++; else _fail++;
}
int main() {
    DynamArr<int, 1> tester;
    tester.push(21);
    tester.push(-1);
    _test(1, -1, tester[1]);
    tester.pop();
    try {
        tester[1];
        _test(2, 1, 2);
    } catch (std::string s) {
        _test(2, 1, (s == "Unable to access out-of-bounds index" ? 1 : 0));
    } catch (...) {
        _test(2, 1, 2);
    }
    _test(3, 1, tester.length);
    try {
        tester.pop();
        tester.pop();
        _test(4, 1, 2);
    } catch (std::string s) {
        _test(4, 1, (s == "Cannot pop a empty vector" ? 1 : 0));
    } catch (...) {
        _test(4, 1, 2);
    }
    std::cout << "---------------------\n";
    std::cout << _pass << " passed, " << _fail << " failed\n";
    return 0;
}
